#!/bin/sh
set -eu
echo "oracle-solve-start"
echo "solution-root=/solution"
ls -la /solution /solution/src
SOLUTION_ROOT=/solution
if [ ! -d "$SOLUTION_ROOT" ]; then SOLUTION_ROOT=/app/solution; fi
# Generated by batch_authoring_pass.py; solution files remain task-owned.
cp -a "$SOLUTION_ROOT/ROOT_CAUSE.txt" /app/ROOT_CAUSE.txt
mkdir -p /app/src
cp -a "$SOLUTION_ROOT/src/Prediction.h" /app/src/Prediction.h
echo "oracle-solve-copied"
